package cn.trial.videosearch.exports;

import cn.trial.videosearch.admin.*;
import cn.trial.videosearch.evidence.InputRejected;
import cn.trial.videosearch.support.CanonicalJson;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import java.sql.Timestamp;
import java.util.*;

@Service
public class ExportJobs {
    public record Create(UUID requestId,UUID collectionId,long collectionRevision,int part,boolean nativeVideo,boolean normalizedVideo){}
    public record Control(UUID requestId,long expectedRevision,String action,String reason){}
    public record Lease(String workerId,long generation){}
    public record Claim(String workerId,List<String> contracts){}
    public record Complete(String workerId,long generation,String artifactSha256,long artifactBytes){}
    public record Fail(String workerId,long generation,String errorCode){}
    public record Transfer(UUID id,UUID export,ExportFiles.Artifact artifact,long start,long end){}
    private static final Set<String> ERRORS=Set.of("export_source_changed","export_asset_unavailable","export_artifact_changed","export_artifact_unavailable","export_storage_full","export_storage_busy","export_timeout","export_worker_error","export_interrupted");
    private static final String VIEW="SELECT export_id,collection_id,collection_revision,part,state,revision,attempts,next_attempt_at,last_error_code,artifact_sha256,artifact_bytes,artifact_expires_at,created_at,updated_at,(manifest->>'parts')::integer AS parts,jsonb_array_length(manifest->'assets') AS asset_count,(manifest->>'video_count')::integer AS video_count,jsonb_array_length(manifest->'missing_attachments') AS missing_attachment_count,EXISTS(SELECT 1 FROM evidence_export_attempts a WHERE a.export_id=evidence_exports.export_id AND a.reclaimed_at IS NULL) AS artifact_cleanup_pending FROM evidence_exports";
    private final JdbcTemplate db;private final ExportPlans plans;private final ExportFiles files;private final UserService users;
    private final TransactionTemplate tx;private final ExportRuntime runtime;private final ExportArtifactLifecycle lifecycle;
    public ExportJobs(JdbcTemplate db,ExportPlans plans,ExportFiles files,UserService users,ExportArtifactLifecycle lifecycle,PlatformTransactionManager manager,ExportRuntime runtime){this.db=db;this.plans=plans;this.files=files;this.users=users;this.lifecycle=lifecycle;this.runtime=runtime;tx=new TransactionTemplate(manager);tx.setTimeout(10);}
    public void requireEnabled(){runtime.requireInstalled();}
    private void lock(){db.execute("SELECT pg_advisory_xact_lock(918273695)");}
    private void commandLock(){db.execute("SELECT pg_advisory_xact_lock(918273692)");lock();}
    private static void worker(String id,long generation){if(id==null||!id.matches("[A-Za-z0-9_.-]{1,100}")||generation<1)throw new IllegalArgumentException("Invalid export lease");}
    private Map<String,Object> row(UUID id){var rows=db.queryForList("SELECT *,manifest_payload AS payload,coalesce(artifact_expires_at,updated_at+interval '24 hours')>clock_timestamp() AS artifact_not_expired FROM evidence_exports WHERE export_id=?",id);if(rows.size()!=1)throw new InputRejected(404,"export_unavailable");return rows.getFirst();}
    private Map<String,Object> owned(UUID id,String owner,long generation){
        worker(owner,generation);var rows=db.queryForList("SELECT *,manifest_payload AS payload FROM evidence_exports WHERE export_id=? AND state='active' AND lease_owner=? AND lease_generation=? AND lease_expires_at>clock_timestamp() FOR UPDATE",id,owner,generation);
        if(rows.size()!=1)throw new InputRejected(409,"export_lease_expired");var value=rows.getFirst();if(!Boolean.TRUE.equals(users.status((String)value.get("actor_id"),((Number)value.get("actor_revision")).longValue()).get("valid")))throw new InputRejected(409,"export_account_changed");return value;
    }
    private Map<String,Object> owner(UUID id,String actor,boolean current){var value=row(id);if(!actor.equals(value.get("actor_id")))throw new InputRejected(404,"export_unavailable");if(current)plans.assertCurrent(ExportPlans.decode((String)value.get("payload")));return value;}
    private Map<String,Object> prior(UUID id,String operation,String actor,String sha){var values=db.queryForList("SELECT operation,actor_id,request_sha256,response::text AS payload FROM application_command_receipts WHERE request_id=?",id);if(values.isEmpty())return null;var old=values.getFirst();if(!operation.equals(old.get("operation"))||!actor.equals(old.get("actor_id"))||!sha.equals(old.get("request_sha256")))throw new InputRejected(409,"command_request_conflict");return ExportPlans.decode((String)old.get("payload"));}
    private Map<String,Object> receipt(UUID request,String operation,String actor,String sha,Map<String,Object> response){db.update("INSERT INTO application_command_receipts(request_id,operation,actor_id,request_sha256,response) VALUES(?,?,?,?,?::jsonb)",request,operation,actor,sha,CanonicalJson.encode(response,65536).payload());audit(actor,operation,response,request);return response;}
    private void audit(String actor,String action,Map<String,Object> result,UUID request){db.update("INSERT INTO audit_events(actor_id,action,result,request_id) VALUES(?,?,?,?)",actor,action,CanonicalJson.encode(result,65536).payload(),request);}
    public Map<String,Object> create(Create body,String actor,long actorRevision)throws Exception{
        requireEnabled();if(body==null||body.requestId()==null||body.collectionId()==null||body.collectionRevision()<1||body.part()<1||body.part()>100)throw new IllegalArgumentException();
        String sha=CanonicalJson.encode(Map.of("collection",body.collectionId().toString(),"revision",body.collectionRevision(),"part",body.part(),"native",body.nativeVideo(),"normalized",body.normalizedVideo()),8192).sha256();
        var replay=prior(body.requestId(),"exports.create",actor,sha);if(replay!=null)return replay;
        runtime.requireProducing(false);
        var manifest=plans.prepare(body.collectionId(),body.collectionRevision(),body.part(),body.normalizedVideo(),actor);UUID id=UUID.nameUUIDFromBytes(("export:"+body.requestId()).getBytes(java.nio.charset.StandardCharsets.UTF_8));
        return tx.execute(status->{commandLock();var old=prior(body.requestId(),"exports.create",actor,sha);if(old!=null)return old;runtime.requireProducing(true);runtime.requireConsumer(ExportRuntime.needsLargeNative(ExportPlans.decode(manifest.payload())));plans.assertDatabaseCurrent(ExportPlans.decode(manifest.payload()));
            if(db.queryForObject("SELECT count(*) FROM evidence_exports WHERE state IN ('queued','active')",Long.class)>=16)throw new InputRejected(429,"export_queue_full");
            db.update("INSERT INTO evidence_exports(export_id,collection_id,collection_revision,part,actor_id,actor_revision,manifest,manifest_payload,manifest_sha256) VALUES(?,?,?,?,?,?,?::jsonb,?,?)",id,body.collectionId(),body.collectionRevision(),body.part(),actor,actorRevision,manifest.payload(),manifest.payload(),manifest.sha256());return receipt(body.requestId(),"exports.create",actor,sha,summary(row(id)));});
    }
    public Map<String,Object> info(UUID collection,long revision){requireEnabled();return plans.info(collection,revision);}
    public Map<String,Object> read(UUID id,String actor){requireEnabled();var values=db.queryForList(VIEW+" WHERE export_id=? AND actor_id=?",id,actor);if(values.size()!=1)throw new InputRejected(404,"export_unavailable");return summary(values.getFirst());}
    public Map<String,Object> list(UUID collection,String actor,int limit,UUID after){
        requireEnabled();if(limit<1||limit>30)throw new IllegalArgumentException();
        Timestamp cursor=null;if(after!=null){var prior=db.queryForList("SELECT created_at FROM evidence_exports WHERE export_id=? AND actor_id=? AND collection_id=?",after,actor,collection);if(prior.size()!=1)throw new IllegalArgumentException("Invalid export cursor");cursor=(Timestamp)prior.getFirst().get("created_at");}
        var rows=db.queryForList(VIEW+" WHERE actor_id=? AND collection_id=? AND (?::uuid IS NULL OR (created_at,export_id)<(?::timestamptz,?::uuid)) ORDER BY created_at DESC,export_id DESC LIMIT ?",actor,collection,after,cursor,after,limit+1);boolean more=rows.size()>limit;var page=rows.subList(0,Math.min(limit,rows.size()));var result=new LinkedHashMap<String,Object>();result.put("items",page.stream().map(this::summary).toList());result.put("has_more",more);result.put("next_cursor",more?page.getLast().get("export_id").toString():null);return result;
    }
    private Map<String,Object> summary(Map<String,Object> row){
        var result=new LinkedHashMap<String,Object>();for(String key:List.of("export_id","collection_id","collection_revision","part","state","revision","attempts","next_attempt_at","last_error_code","artifact_sha256","artifact_bytes","artifact_expires_at","created_at","updated_at")){Object value=row.get(key);result.put(key,value instanceof UUID id?id.toString():value instanceof Timestamp time?time.toInstant().toString():value);}
        if(row.containsKey("parts")){for(String key:List.of("parts","asset_count","video_count","missing_attachment_count","artifact_cleanup_pending"))result.put(key,row.get(key));return result;}
        var manifest=ExportPlans.decode((String)row.get("payload"));result.put("parts",manifest.get("parts"));result.put("asset_count",ExportPlans.rows(manifest.get("assets")).size());result.put("video_count",ExportPlans.rows(manifest.get("assets")).stream().filter(asset->!"image".equals(asset.get("kind"))).count());result.put("missing_attachment_count",ExportPlans.rows(manifest.get("missing_attachments")).size());result.put("artifact_cleanup_pending",Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM evidence_export_attempts WHERE export_id=? AND reclaimed_at IS NULL)",Boolean.class,row.get("export_id"))));return result;
    }
    public Map<String,Object> control(UUID id,Control body,String actor,long actorRevision){
        requireEnabled();if(body==null||body.requestId()==null||body.expectedRevision()<1||body.action()==null||!Set.of("cancel","retry").contains(body.action())||body.reason()==null||body.reason().isBlank()||body.reason().length()>300||body.reason().chars().anyMatch(Character::isISOControl))throw new IllegalArgumentException();owner(id,actor,"retry".equals(body.action()));
        String sha=CanonicalJson.encode(Map.of("export",id.toString(),"revision",body.expectedRevision(),"action",body.action(),"reason",body.reason()),8192).sha256();
        return tx.execute(status->{commandLock();var old=prior(body.requestId(),"exports.control",actor,sha);if(old!=null)return old;if("retry".equals(body.action()))runtime.requireProducing(true);var value=owner(id,actor,false);if("retry".equals(body.action()))plans.assertDatabaseCurrent(ExportPlans.decode((String)value.get("payload")));if("retry".equals(body.action()))runtime.requireConsumer(ExportRuntime.needsLargeNative(ExportPlans.decode((String)value.get("payload"))));
            if(((Number)value.get("revision")).longValue()!=body.expectedRevision())throw new InputRejected(409,"export_revision_conflict");if("retry".equals(body.action())&&!"failed".equals(value.get("state"))||"cancelled".equals(value.get("state")))throw new InputRejected(409,"export_state_conflict");
            boolean retry=body.action().equals("retry");db.update("UPDATE evidence_exports SET state=?,revision=revision+1,actor_revision=?,attempts=CASE WHEN ? THEN 0 ELSE attempts END,lease_generation=lease_generation+1,lease_owner=NULL,lease_expires_at=NULL,next_attempt_at=clock_timestamp(),last_error_code=NULL,updated_at=clock_timestamp() WHERE export_id=?",retry?"queued":"cancelled",actorRevision,retry,id);return receipt(body.requestId(),"exports.control",actor,sha,summary(row(id)));});
    }
    public Map<String,Object> claim(Claim body){
        requireEnabled();if(body==null||body.contracts()==null||body.contracts().size()>4||!body.contracts().contains("evidence-export-v1")||new HashSet<>(body.contracts()).size()!=body.contracts().size()||body.contracts().stream().anyMatch(value->value==null||!value.matches("[a-z][a-z0-9-]{0,79}")))throw new IllegalArgumentException();worker(body.workerId(),1);
        return tx.execute(status->{lock();db.update("UPDATE evidence_exports SET state=CASE WHEN attempts>=3 THEN 'failed' ELSE 'queued' END,revision=revision+1,lease_owner=NULL,lease_expires_at=NULL,next_attempt_at=clock_timestamp()+interval '5 seconds',last_error_code='export_lease_expired',updated_at=clock_timestamp() WHERE state='active' AND lease_expires_at<=clock_timestamp()");if(!runtime.producing(true))return Map.of("job_available",false,"module_enabled",false);if(db.queryForObject("SELECT count(*) FROM evidence_exports WHERE state='active'",Long.class)>=1)return Map.of("job_available",false);
            var candidates=db.queryForList("SELECT e.*,manifest_payload AS payload FROM evidence_exports e WHERE state='queued' AND next_attempt_at<=clock_timestamp() AND (? OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(e.manifest->'assets') a WHERE a->>'kind'='native' AND (a->>'bytes')::bigint>16777216)) ORDER BY created_at,export_id FOR UPDATE SKIP LOCKED LIMIT 1",body.contracts().contains(ExportRuntime.LARGE_NATIVE));if(candidates.isEmpty())return Map.of("job_available",false);var job=candidates.getFirst();
            if(!Boolean.TRUE.equals(users.status((String)job.get("actor_id"),((Number)job.get("actor_revision")).longValue()).get("valid"))){db.update("UPDATE evidence_exports SET state='failed',revision=revision+1,last_error_code='export_account_changed',updated_at=clock_timestamp() WHERE export_id=?",job.get("export_id"));return Map.of("job_available",false);}
            try{plans.assertDatabaseCurrent(ExportPlans.decode((String)job.get("payload")));}catch(InputRejected|AdminService.Rejected error){db.update("UPDATE evidence_exports SET state='failed',revision=revision+1,last_error_code='export_source_changed',updated_at=clock_timestamp() WHERE export_id=?",job.get("export_id"));return Map.of("job_available",false);}
            var updated=db.queryForList("UPDATE evidence_exports SET state='active',attempts=attempts+1,revision=revision+1,lease_generation=lease_generation+1,lease_owner=?,lease_expires_at=clock_timestamp()+interval '120 seconds',updated_at=clock_timestamp() WHERE export_id=? RETURNING lease_generation",body.workerId(),job.get("export_id")).getFirst();lifecycle.register((UUID)job.get("export_id"),((Number)updated.get("lease_generation")).longValue(),body.workerId(),(String)job.get("manifest_sha256"));return Map.of("job",Map.of("export_id",job.get("export_id").toString(),"generation",updated.get("lease_generation"),"manifest_payload",job.get("payload"),"manifest_sha256",job.get("manifest_sha256")));});
    }
    public Map<String,Object> renew(UUID id,Lease body){requireEnabled();if(body==null)throw new IllegalArgumentException();return tx.execute(status->{lock();owned(id,body.workerId(),body.generation());db.update("UPDATE evidence_exports SET lease_expires_at=clock_timestamp()+interval '120 seconds',updated_at=clock_timestamp() WHERE export_id=?",id);return Map.of("renewed",true);});}
    public Map<String,Object> workerSnapshot(UUID id,String worker,long generation){requireEnabled();return tx.execute(status->{lock();var value=owned(id,worker,generation);plans.assertDatabaseCurrent(ExportPlans.decode((String)value.get("payload")));return value;});}
    public Map<String,Object> complete(UUID id,Complete body){
        requireEnabled();if(body==null)throw new IllegalArgumentException();worker(body.workerId(),body.generation());var previous=row(id);
        if(completed(previous,body))return Map.of("completed",true);
        var snapshot=workerSnapshot(id,body.workerId(),body.generation());files.verify(id,body.generation(),(String)snapshot.get("payload"),(String)snapshot.get("manifest_sha256"),body.artifactSha256(),body.artifactBytes());
        return tx.execute(status->{lock();var current=row(id);if(completed(current,body))return Map.of("completed",true);var valid=owned(id,body.workerId(),body.generation());plans.assertDatabaseCurrent(ExportPlans.decode((String)valid.get("payload")));db.update("UPDATE evidence_exports SET state='completed',revision=revision+1,artifact_generation=?,artifact_sha256=?,artifact_bytes=?,artifact_expires_at=clock_timestamp()+interval '24 hours',lease_expires_at=NULL,updated_at=clock_timestamp(),last_error_code=NULL WHERE export_id=?",body.generation(),body.artifactSha256(),body.artifactBytes(),id);audit((String)valid.get("actor_id"),"exports.complete",Map.of("export_id",id.toString(),"sha256",body.artifactSha256(),"bytes",body.artifactBytes()),id);return Map.of("completed",true);});
    }
    private static boolean completed(Map<String,Object> row,Complete body){return "completed".equals(row.get("state"))&&Objects.equals(row.get("lease_owner"),body.workerId())&&Objects.equals(row.get("artifact_sha256"),body.artifactSha256())&&row.get("artifact_generation") instanceof Number generation&&generation.longValue()==body.generation()&&((Number)row.get("artifact_bytes")).longValue()==body.artifactBytes();}
    public Map<String,Object> fail(UUID id,Fail body){requireEnabled();if(body==null||body.errorCode()==null||!ERRORS.contains(body.errorCode()))throw new IllegalArgumentException();return tx.execute(status->{lock();var valid=owned(id,body.workerId(),body.generation());int attempts=((Number)valid.get("attempts")).intValue();String state=attempts>=3?"failed":"queued";db.update("UPDATE evidence_exports SET state=?,revision=revision+1,lease_owner=NULL,lease_expires_at=NULL,last_error_code=?,next_attempt_at=clock_timestamp()+(?*interval '1 second'),updated_at=clock_timestamp() WHERE export_id=?",state,body.errorCode(),Math.min(60,5*(1<<Math.min(4,attempts))),id);return Map.of("state",state);});}
    private static void requireNotExpired(Map<String,Object> value){
        if(!Boolean.TRUE.equals(value.get("artifact_not_expired")))throw new InputRejected(410,"export_expired");
    }
    public Transfer download(UUID id,String actor,String range){
        requireEnabled();var value=owner(id,actor,true);if("export_expired".equals(value.get("last_error_code")))throw new InputRejected(410,"export_expired");if(!"completed".equals(value.get("state")))throw new InputRejected(409,"export_not_ready");requireNotExpired(value);
        long[] window=cn.trial.videosearch.evidence.ArchiveController.parseRange(range,((Number)value.get("artifact_bytes")).longValue());if(window==null)throw new InputRejected(416,"export_invalid_range");
        var artifact=files.verify(id,((Number)value.get("artifact_generation")).longValue(),(String)value.get("payload"),(String)value.get("manifest_sha256"),(String)value.get("artifact_sha256"),((Number)value.get("artifact_bytes")).longValue());owner(id,actor,true);
        UUID transfer=UUID.randomUUID();
        tx.executeWithoutResult(status->{lock();var current=owner(id,actor,false);if(!"completed".equals(current.get("state")))throw new InputRejected(409,"export_not_ready");plans.assertDatabaseCurrent(ExportPlans.decode((String)current.get("payload")));requireNotExpired(current);db.update("INSERT INTO evidence_export_transfers(transfer_id,export_id,actor_id,artifact_sha256,range_start,range_end,expected_bytes) VALUES(?,?,?,?,?,?,?)",transfer,id,actor,artifact.sha256(),window[0],window[1],window[1]-window[0]+1);});return new Transfer(transfer,id,artifact,window[0],window[1]);
    }
    public void finishTransfer(Transfer transfer,long sent,String state){if(!Set.of("server_complete","interrupted","failed").contains(state)||sent<0||sent>transfer.end()-transfer.start()+1)throw new IllegalArgumentException();db.update("UPDATE evidence_export_transfers SET sent_bytes=?,state=?,finished_at=clock_timestamp() WHERE transfer_id=? AND state='streaming'",sent,state,transfer.id());}
    public Map<String,Object> transfers(UUID id,String actor,int limit,UUID after){
        requireEnabled();owner(id,actor,false);if(limit<1||limit>30)throw new IllegalArgumentException();
        Timestamp cursor=null;if(after!=null){var prior=db.queryForList("SELECT started_at FROM evidence_export_transfers WHERE export_id=? AND transfer_id=?",id,after);if(prior.size()!=1)throw new IllegalArgumentException("Invalid transfer cursor");cursor=(Timestamp)prior.getFirst().get("started_at");}
        var rows=db.queryForList("SELECT transfer_id,artifact_sha256,range_start,range_end,expected_bytes,sent_bytes,state,started_at,finished_at,state='streaming' AND started_at<clock_timestamp()-interval '20 minutes' AS stale FROM evidence_export_transfers WHERE export_id=? AND (?::uuid IS NULL OR (started_at,transfer_id)<(?::timestamptz,?::uuid)) ORDER BY started_at DESC,transfer_id DESC LIMIT ?",id,after,cursor,after,limit+1);boolean more=rows.size()>limit;var page=rows.subList(0,Math.min(limit,rows.size()));var result=new LinkedHashMap<String,Object>();result.put("items",page.stream().map(value->{var converted=new LinkedHashMap<String,Object>();value.forEach((key,raw)->converted.put(key,raw instanceof UUID uuid?uuid.toString():raw instanceof Timestamp time?time.toInstant().toString():raw));return converted;}).toList());result.put("has_more",more);result.put("next_cursor",more?page.getLast().get("transfer_id").toString():null);return result;
    }
}
